+        {
+            packet.ReadInt16("TrapLevel");
+
+            var slotsCount = packet.ReadInt32("SlotsCount");
+            var petsCount = packet.ReadInt32("PetsCount");
+
+            packet.ReadBit("HasJournalLock");
